#!/usr/bin/env bash
set -euo pipefail
command -v psql >/dev/null || { echo 'PostgreSQL 16+ psql is required'; exit 2; }
major=$(psql --version | sed -E 's/.* ([0-9]+).*/\1/'); ((major>=16)) || { echo 'PostgreSQL 16+ is required'; exit 2; }
DB_NAME="citem_phase2_2a_${$}"; sql_file=$(mktemp); cleanup(){ rm -f "$sql_file"; dropdb --if-exists "$DB_NAME" >/dev/null 2>&1||true;};trap cleanup EXIT
createdb "$DB_NAME"
psql -v ON_ERROR_STOP=1 -d "$DB_NAME" <<'SQL' >/dev/null
do $$begin create role authenticated;exception when duplicate_object then null;end$$;do $$begin create role service_role;exception when duplicate_object then null;end$$;do $$begin create role anon;exception when duplicate_object then null;end$$;create extension pgcrypto;create schema auth;create table auth.users(id uuid primary key,raw_user_meta_data jsonb not null default '{}');create function auth.uid()returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;create function auth.jwt()returns jsonb language sql stable as $$select '{}'::jsonb$$;create schema storage;create table storage.buckets(id text primary key,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);create table storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text,name text,owner uuid);create function storage.foldername(name text)returns text[] language sql immutable as $$select string_to_array(name,'/')$$;create function storage.filename(name text)returns text language sql immutable as $$select(string_to_array(name,'/'))[array_length(string_to_array(name,'/'),1)]$$;
SQL
for migration in supabase/migrations/*.sql;do printf "\\i '%s/%s'\n" "$PWD" "$migration";done >"$sql_file"
psql -v ON_ERROR_STOP=1 -d "$DB_NAME" -f "$sql_file" >/dev/null
psql -v ON_ERROR_STOP=1 -d "$DB_NAME" <<'SQL' >/dev/null
insert into auth.users(id)values('10000000-0000-4000-8000-000000000001'),('10000000-0000-4000-8000-000000000002');
insert into projects(id,owner_id,name,research_type)values('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','One','CTI'),('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','Two','CTI');
create table test_claims(label text primary key,feed_id uuid,run_id uuid,token uuid,url_hash text);
do $$declare f research_feed_sources;c record;oldrun uuid;oldtoken uuid;oldhealth research_feed_health;begin
 if exists(select 1 from information_schema.columns where table_schema='public' and table_name='research_feed_sources' and column_name='fetch_lease_token')then raise exception 'raw lease token column exists';end if;
 f:=create_research_feed('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','Feed','', 'https://example.com/feed',repeat('a',64),true);
 -- Cross-user owner verification.
 begin perform set_research_feed_enabled('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000001',f.id,false);raise exception 'cross-user accepted';exception when no_data_found then null;end;
 select * into c from claim_research_feed_fetch('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',f.id);oldrun:=c.run_id;oldtoken:=c.lease_token;if c.configured_url<>'https://example.com/feed' or c.request_url_hash<>repeat('a',64)then raise exception 'claim snapshot mismatch';end if;begin perform edit_research_feed('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',f.id,'Feed','','https://new.example/feed',repeat('9',64),true);raise exception 'active URL edit accepted';exception when raise_exception then null;end;if c.configured_url<>'https://example.com/feed'then raise exception 'claim snapshot changed';end if;
 -- Expired recovery closes the abandoned run and binds a replacement token.
 update research_feed_sources set fetch_lease_expires_at=clock_timestamp()-interval '1 second',next_eligible_fetch_at=null where id=f.id;update research_feed_fetch_runs set lease_expires_at=clock_timestamp()-interval '1 second' where id=oldrun;
 select * into c from claim_research_feed_fetch('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',f.id);if(select status from research_feed_fetch_runs where id=oldrun)<>'FAILED' or(select error_code from research_feed_fetch_runs where id=oldrun)<>'LEASE_EXPIRED' then raise exception 'expired run not closed';end if;
 begin perform complete_research_feed_fetch('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',f.id,oldrun,oldtoken,repeat('a',64),'NOT_MODIFIED','UNKNOWN','https://example.com/feed',304,0,null,null,'[]');raise exception 'stale completion accepted';exception when raise_exception then null;end;
 begin perform fail_research_feed_fetch('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',f.id,oldrun,oldtoken,repeat('a',64),'INTERNAL_ERROR','x');raise exception 'stale failure accepted';exception when raise_exception then null;end;
 if(select fetch_lease_token_hash from research_feed_sources where id=f.id)is distinct from encode(digest(c.lease_token::text,'sha256'),'hex') then raise exception 'stale callback cleared current lease';end if;
 oldhealth:=(select health_status from research_feed_sources where id=f.id);begin perform fail_research_feed_fetch('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',f.id,gen_random_uuid(),gen_random_uuid(),repeat('a',64),'INTERNAL_ERROR','x');raise exception 'missing run accepted';exception when raise_exception then null;end;if(select health_status from research_feed_sources where id=f.id)<>oldhealth then raise exception 'missing failure changed health';end if;
 begin perform complete_research_feed_fetch('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',f.id,c.run_id,c.lease_token,repeat('f',64),'NOT_MODIFIED','UNKNOWN','https://example.com/feed',304,0,null,null,'[]');raise exception 'stale URL accepted';exception when raise_exception then null;end;
 perform complete_research_feed_fetch('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',f.id,c.run_id,c.lease_token,c.request_url_hash,'NOT_MODIFIED','UNKNOWN','https://example.com/feed',304,0,null,null,'[]');
 perform archive_research_feed('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',f.id);f:=restore_research_feed('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',f.id);if f.enabled or f.archived_at is not null then raise exception 'restore not paused';end if;
 -- Transactional database feed limit (the restored feed is number one).
 for i in 2..100 loop perform create_research_feed('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','Feed'||i,'','https://example.com/'||i,encode(digest(i::text,'sha256'),'hex'),false);end loop;begin perform create_research_feed('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','Too many','','https://example.com/101',repeat('e',64),false);raise exception 'feed limit exceeded';exception when raise_exception then null;end;
end$$;
-- Two owned feeds and live claims for the real concurrent canonicalization check.
do $$declare f research_feed_sources;c record;begin
 f:=create_research_feed('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002','Concurrent A','','https://one.example/feed',repeat('1',64),true);select * into c from claim_research_feed_fetch('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',f.id);insert into test_claims values('a',f.id,c.run_id,c.lease_token,c.request_url_hash);
 f:=create_research_feed('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002','Concurrent B','','https://two.example/feed',repeat('2',64),true);select * into c from claim_research_feed_fetch('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',f.id);insert into test_claims values('b',f.id,c.run_id,c.lease_token,c.request_url_hash);end$$;
SQL
payload="jsonb_build_array(jsonb_build_object('title','Shared','summary_text','Body','categories','[]'::jsonb,'canonical_url','https://article.example/x','url_hash',repeat('b',64),'content_hash',repeat('c',64)))"
for label in a b;do
 IFS='|' read -r feed run token hash < <(psql -At -d "$DB_NAME" -c "select feed_id,run_id,token,url_hash from test_claims where label='$label'")
 psql -v ON_ERROR_STOP=1 -d "$DB_NAME" -c "select complete_research_feed_fetch('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002','$feed','$run','$token','$hash','SUCCEEDED','RSS','https://example.com/feed',200,100,null,null,$payload);" >/dev/null &
done
wait
psql -v ON_ERROR_STOP=1 -d "$DB_NAME" <<'SQL' >/dev/null
do $$declare changed_before timestamptz;f uuid;r uuid;t uuid;h text;begin
 if(select count(*)from research_items where project_id='20000000-0000-4000-8000-000000000002')<>1 then raise exception 'concurrent URL/content dedup failed';end if;if exists(select 1 from research_items i where not exists(select 1 from research_item_fingerprints f where f.research_item_id=i.id))then raise exception 'orphan item';end if;
 -- Malformed completion rolls back, unchanged repeat preserves content_changed_at, changed content sets it.
 select feed_id into f from test_claims where label='a';update research_feed_sources set enabled=true,next_eligible_fetch_at=null where id=f;select run_id,lease_token,request_url_hash into r,t,h from claim_research_feed_fetch('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',f);begin perform complete_research_feed_fetch('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',f,r,t,h,'SUCCEEDED','RSS','https://example.com/feed',304,0,null,null,'[]');raise exception 'SUCCEEDED 304 accepted';exception when data_exception then null;end;begin perform complete_research_feed_fetch('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',f,r,t,h,'NOT_MODIFIED','UNKNOWN','https://example.com/feed',200,0,null,null,'[]');raise exception 'NOT_MODIFIED 200 accepted';exception when data_exception then null;end;begin perform complete_research_feed_fetch('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',f,r,t,h,'NOT_MODIFIED','UNKNOWN','https://example.com/feed',304,0,null,null,jsonb_build_array(jsonb_build_object('title','x')));raise exception 'NOT_MODIFIED items accepted';exception when data_exception then null;end;begin perform complete_research_feed_fetch('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',f,r,t,h,'SUCCEEDED','RSS','ftp://example.com/feed',200,0,null,null,'[]');raise exception 'non-http final URL accepted';exception when data_exception then null;end;begin perform complete_research_feed_fetch('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',f,r,t,h,'SUCCEEDED','RSS',null,200,0,null,null,null);raise exception 'null contract accepted';exception when data_exception then null;end;if(select fetch_lease_run_id from research_feed_sources where id=f)is distinct from r then raise exception 'malformed completion cleared lease';end if;begin perform complete_research_feed_fetch('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',f,r,t,h,'SUCCEEDED','RSS','https://example.com/feed',200,100,null,null,jsonb_build_array(jsonb_build_object('title',repeat('x',501),'content_hash',repeat('c',64),'categories','[]'::jsonb)));raise exception 'malformed accepted';exception when data_exception then null;end;if(select status from research_feed_fetch_runs where id=r)<>'RUNNING'then raise exception 'malformed did not rollback';end if;
 perform complete_research_feed_fetch('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',f,r,t,h,'SUCCEEDED','RSS','https://example.com/feed',200,100,null,null,jsonb_build_array(jsonb_build_object('title','Shared','summary_text','Body','categories','[]'::jsonb,'canonical_url','https://article.example/x','url_hash',repeat('b',64),'content_hash',repeat('c',64))));changed_before:=(select content_changed_at from research_items where project_id='20000000-0000-4000-8000-000000000002');if changed_before is not null then raise exception 'unchanged marked changed';end if;
 update research_feed_sources set next_eligible_fetch_at=null where id=f;select run_id,lease_token,request_url_hash into r,t,h from claim_research_feed_fetch('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',f);perform complete_research_feed_fetch('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',f,r,t,h,'SUCCEEDED','RSS','https://example.com/feed',200,100,null,null,jsonb_build_array(jsonb_build_object('title','Shared changed','summary_text','Body 2','categories','[]'::jsonb,'canonical_url','https://article.example/x','url_hash',repeat('b',64),'content_hash',repeat('d',64))));if(select content_changed_at from research_items where project_id='20000000-0000-4000-8000-000000000002')is null then raise exception 'change not recorded';end if;
 update research_feed_sources set next_eligible_fetch_at=null where id=f;select run_id,lease_token,request_url_hash into r,t,h from claim_research_feed_fetch('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',f);perform fail_research_feed_fetch('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',f,r,t,h,'CONNECTION_TIMEOUT','The feed connection timed out.');if(select status from research_feed_fetch_runs where id=r)<>'FAILED' or(select fetch_lease_run_id from research_feed_sources where id=f)is not null then raise exception 'failure did not finalize and release lease';end if;
end$$;
SQL
# Authenticated clients have neither mutation policies nor workflow function execution.
if psql -d "$DB_NAME" -v ON_ERROR_STOP=1 -c "set role authenticated;select complete_research_feed_fetch(null,null,null,null,null,null,'NOT_MODIFIED','UNKNOWN','',304,0,null,null,'[]');" >/dev/null 2>&1;then echo 'authenticated completion unexpectedly allowed' >&2;exit 1;fi
if psql -d "$DB_NAME" -v ON_ERROR_STOP=1 -c "set role authenticated;update research_feed_sources set health_status='HEALTHY';" >/dev/null 2>&1;then echo 'direct workflow update unexpectedly allowed' >&2;exit 1;fi
echo "Phase 2.2A PostgreSQL $major trusted-boundary, lease, lifecycle, concurrent-dedup and rollback assertions passed (not live Supabase validation)."
